WITH filtered AS (SELECT id, supplier_name, country, city, rating, INITCAP(TRIM(supplier_name)) AS supplier_name_title FROM suppliers WHERE city IS NOT NULL AND city = 'Bangkok') SELECT s.id, s.supplier_name, s.city, s.supplier_name_title, latest.brand, latest.stock_qty FROM filtered s LEFT JOIN LATERAL (SELECT c.brand, c.stock_qty FROM products c WHERE c.supplier_id = s.id ORDER BY c.price DESC, c.id DESC LIMIT 1) latest ON TRUE;
